-- Esquema original do pacote DIGITALGOV (v1.0.0-mvp)
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('ADMIN','EDITOR','APPROVER','VIEWER')), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS channels (id INTEGER PRIMARY KEY, name TEXT NOT NULL, description TEXT DEFAULT '', is_public INTEGER NOT NULL DEFAULT 0, created_by INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY, channel_id INTEGER NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'RASCUNHO' CHECK(status IN ('RASCUNHO','EM_REVISAO','APROVADO','PUBLICADO')), author_id INTEGER NOT NULL, approver_id INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, published_at TEXT, FOREIGN KEY(channel_id) REFERENCES channels(id), FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS campaigns (id INTEGER PRIMARY KEY, name TEXT NOT NULL, objective TEXT NOT NULL, channel_id INTEGER, starts_on TEXT, ends_on TEXT, status TEXT DEFAULT 'PLANEJADA', owner_id INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS contacts (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT, category TEXT NOT NULL DEFAULT 'PUBLICO', consent INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tickets (id INTEGER PRIMARY KEY, contact_id INTEGER, subject TEXT NOT NULL, description TEXT NOT NULL, priority TEXT NOT NULL DEFAULT 'NORMAL' CHECK(priority IN ('BAIXA','NORMAL','ALTA')), status TEXT NOT NULL DEFAULT 'ABERTO' CHECK(status IN ('ABERTO','EM_ATENDIMENTO','RESOLVIDO')), assigned_to INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(contact_id) REFERENCES contacts(id));
CREATE TABLE IF NOT EXISTS deliveries (id INTEGER PRIMARY KEY, post_id INTEGER NOT NULL, target TEXT NOT NULL, channel TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDENTE_INTEGRACAO', created_at TEXT NOT NULL, FOREIGN KEY(post_id) REFERENCES posts(id));
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY, user_id INTEGER, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INTEGER, at TEXT NOT NULL, detail TEXT DEFAULT '{}');
